/* From Uiverse.io by garerim - Tags: loader */
.__UIV_SCOPE__ .anim-box {
  width: 200px;
  height: 200px;
  border: 5px solid #333;
  margin: 100px auto;
  position: relative;
}

.__UIV_SCOPE__ .anim-interieur {
  width: 100px;
  height: 50px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
    /* background-color: orange; */
  text-align: center;
}

.__UIV_SCOPE__ .rect {
  background-color: #333;
  display: inline-block;
  height: 60px;
  width: 6px;
  margin: 0px  1px;
  animation: etire 1.2s infinite ease-in-out;
}

@keyframes etire {
  0% {
    transform: scaleY(0.4);
  }

  20% {
    transform: scaleY(1);
  }

  40% {
    transform: scaleY(0.4);
  }

  100% {
    transform: scaleY(0.4);
  }
}

.__UIV_SCOPE__ .rect2 {
  animation-delay: -1.1s;
}

.__UIV_SCOPE__ .rect3 {
  animation-delay: -1s;
}

.__UIV_SCOPE__ .rect4 {
  animation-delay: -0.9s;
}

.__UIV_SCOPE__ .rect5 {
  animation-delay: -0.8s;
}
